from h34 import *
M=mcq;F=tf;S=short;N=num
b='<rect width="720" height="270" fill="#f2f8fd"/><text x="360" y="28" text-anchor="middle" font-size="18" font-weight="bold">Four habits for a happy and healthy life</text>'
items=[("#f7d98b","Eat right","right food, at the","right time, in the","right way (no waste)"),("#b9dc8f","Play and exercise","running, cycling,","skipping, yoga,","open-field games"),("#bcd6f2","Sleep well","enough sleep takes","tiredness away and","helps us focus"),("#f4c3cf","Feel safe","know safe and unsafe","touch; say No and tell","a trusted adult")]
for i,(c,t,a,d,e) in enumerate(items):
    x=18+i*175
    b+=f'<rect x="{x}" y="55" width="162" height="170" rx="16" fill="{c}" stroke="#666" stroke-width="2"/><text x="{x+81}" y="90" text-anchor="middle" font-size="17" font-weight="bold">{t}</text><text x="{x+81}" y="125" text-anchor="middle" font-size="13">{a}</text><text x="{x+81}" y="145" text-anchor="middle" font-size="13">{d}</text><text x="{x+81}" y="165" text-anchor="middle" font-size="13">{e}</text>'
b+='<text x="360" y="255" text-anchor="middle" font-size="13">Take care of the body and the mind to stay happy, healthy and joyful.</text>'
svgfile('c4evs-happy-habits.svg',720,270,b)
chapter(4,'evs','happy-and-healthy-living','Happy and Healthy Living',
 ('When do I feel happy?','We feel happy at different times for different reasons: when we play our favourite games, when we eat tasty food, when we are with friends. This chapter follows a grain of rice or wheat on its long journey from the farm to your plate, and then looks at four things that keep us happy and healthy: eating right, playing, sleeping well and feeling safe. At the end you will plan your own healthy day.'),
 [('The journey of a grain',['We enjoy foods made from grains, pulses and vegetables, and each food item reaches us after a journey.','A grain of rice or wheat travels from the farm to our plate through many steps, and many people and animals make that journey possible.','Farmers sow the seed, look after the crop and harvest it, and cattle help in the fields.','Sellers and shopkeepers bring the grain to us, and family members cook it.','Soil, water, air and sunlight are also needed for the grain to grow, and earthworms and insects help the soil.','From the time a seed is sown till the food reaches our plate, the journey is a remarkable one that takes a lot of hard work.']),
  ('Saying thank you',['When we remember everyone who helped bring food to our plate, with love and gratitude, we feel the value of each grain.','You can think about whom you would like to thank for the food you eat, such as farmers, cattle, shopkeepers and the family cook.','In India, many festivals show gratitude to Mother Nature for food, such as Makar Sankranti, Akshay Tritiya, Raja Utsav, Onam and Lohri.']),
  ('Mindful eating',['The teacher asked the children to sit in a circle with their eyes closed and gave each a peanut.','They followed instructions: put the food in your mouth slowly, feel its surface with your tongue, and chew it gently.','They felt the flavour with the tongue, nose and other senses, and remembered the taste and the texture before swallowing.','The tongue tastes and moves the food, the teeth chew it, and the food gets mixed with saliva in the mouth.','Mindful eating means paying attention to what we eat and how we feel while eating, so we enjoy food more and make healthier choices.']),
  ('Valuing food',['Every grain is precious, and when we waste food we fail to respect the efforts of everyone who helped bring it to us.','You can keep a record for a week of whether you finished your breakfast, lunch and dinner and how you felt.','If someone offers you more food than you need, politely say that you have had enough, and if you do not like something, try a little or leave a small portion without wasting.']),
  ('Play, sports and yoga',['Along with good food we need regular physical activity to stay healthy, like playing in open fields with friends, running, jumping, cycling and skipping.','These activities keep us strong and energetic, and we usually feel happy and fresh after a day of play.','Yoga improves our posture and keeps us happy and active, and you can practise easy yoga poses for a week with your teacher\'s guidance.','The textbook Khel Yoga has many interesting exercises and games.']),
  ('Sleep well too',['After a day of play or exercise, the body needs rest, and good sleep takes away our tiredness and makes us feel fresh.','When we do not get enough sleep it is hard to focus on work or play, and we feel tired, sleepy and irritable.','So enough sleep is as important as healthy food and exercise.','You can note when you slept, when you woke up and how you felt, to see how sleep affects your day.']),
  ('Feeling safe',['Sometimes someone may feel unhappy, unsafe or uncomfortable.','A safe touch, like a comforting hug from your mother or another family member, makes you feel happy and comfortable.','An unsafe touch makes you feel uneasy, scared, confused or uncomfortable, whether it is from someone you know or a stranger.','If anyone makes you feel uncomfortable, it is okay to say No clearly and to tell a trusted adult like your teacher or parents.','You do not have to feel guilty, and you should always speak up if you feel unsafe.','To stay happy and healthy, eat right, exercise, rest and keep both your body and mind safe and cared for.'])],
 [('If soil, water or sunlight were missing, what would happen to a grain?',[('A seed needs soil to grow in and water to drink.','Without these it cannot sprout.'),('Plants make their food using sunlight.','Without sunlight the plant would stay weak and give no grain.'),('So all three are needed for the grain to reach our plate.','Nature plays a big part in our food.')]),
  ('Plan a healthy day with the four habits.',[('Eat breakfast, lunch and dinner on time, with a balanced plate and no waste.','Eat right.'),('Play or do yoga for some time every day.','Exercise.'),('Go to bed on time and sleep peacefully.','Sleep.'),('Remember: if anything makes you feel unsafe, say No and tell a trusted adult.','Feel safe.')])],
 ('Explain what mindful eating is and why it is good for us.',['Pay attention to what we eat and how we feel','Eat slowly, feel the texture and flavour, chew well','Enjoy food more and make healthier choices','Respect food and avoid waste'],['Eating very fast is better','Mindful eating means skipping meals','Watching a screen while eating is mindful']),
 ['A grain\'s journey from farm to plate involves soil, water, sunlight, farmers, cattle, sellers and family.','We should thank everyone who brings us food and never waste food.','Mindful eating means eating slowly and paying attention.','We need play, exercise, yoga and enough sleep to stay healthy.','Know safe and unsafe touch; say No and tell a trusted adult if you feel unsafe.'],
 [M('1',1,'Who helps a grain on its journey from farm to plate?','Farmers, cattle, sellers and family members',[('Only the cook','Many people take part'),('Nobody, grains grow alone','Many people and animals help')],'Many people and animals make the journey possible.'),
  M('2',1,'Which natural things does a grain need to grow?','Soil, water and sunlight',[('Only stones','Stones do not help a grain grow'),('Only fire','Fire would burn it')],'Soil, water and sunlight all help the plant grow.'),
  M('3',1,'How should we eat during mindful eating?','Slowly, paying attention to each bite',[('As fast as possible','Mindful eating is slow'),('While watching TV','It needs attention on the food')],'We notice texture, flavour and chewing.'),
  M('4',1,'Which festival shows gratitude to Mother Nature for food?','Onam',[('Independence Day','That is not about food from nature'),('Children\'s Day','That is not about food from nature')],'Makar Sankranti, Akshay Tritiya, Raja Utsav, Onam and Lohri are examples.'),
  M('5',2,'What do the teeth do to food in the mouth?','They chew it',[('They taste it','The tongue tastes'),('They swallow it','Swallowing is not done by teeth')],'Teeth chew food into small pieces.'),
  M('6',2,'What happens when we do not get enough sleep?','We feel tired and irritable and cannot focus well',[('We feel fresher','Sleep makes us fresh'),('We grow taller at once','Lack of sleep makes us tired')],'Enough sleep is as important as food and exercise.'),
  M('7',2,'Which is an example of a safe touch?','A comforting hug from your mother',[('A touch that scares you','That is an unsafe touch'),('A touch that makes you confused','That is an unsafe touch')],'A safe touch makes you feel happy and comfortable.'),
  M('8',2,'If someone\'s touch makes you uncomfortable, what should you do?','Say No and tell a trusted adult',[('Keep it a secret','You should tell a trusted adult'),('Feel guilty','You do not have to feel guilty')],'Speak up and tell your teacher or parents.'),
  M('9',2,'Which book of exercises and games is named in the chapter?','Khel Yoga',[('Our Wondrous World','That is the EVS book'),('Math-Magic','That is the Maths book')],'Khel Yoga is the Physical Education and Well-being book.'),
  M('10',2,'What does yoga improve?','Our posture and happiness',[('Our eyesight only','The chapter says posture'),('Nothing','Yoga keeps us happy and active')],'Yoga improves posture and keeps us happy and active.'),
  F('11',2,'We should waste food only if we do not like it.',False,'Every grain is precious and wasting food disrespects everyone who helped.'),
  F('12',3,'Regular play and exercise help keep us strong and energetic.',True,'Running, jumping, cycling and skipping keep us fit.')],
 svgs=[('c4evs-happy-habits','Four boxes: eat right, play and exercise, sleep well, feel safe.','Four habits for a happy and healthy life.')],
 keep=['mindful eating','yoga'])
